import sqlite3
DB_PATH = 'reservations.db'

def _grant_table_staff_access(conn, reservation_id, table_id):
    # Reassign the 'server' role on this reservation to the staff covering the new table
    conn.execute('CREATE TABLE IF NOT EXISTS reservation_access (reservation_id TEXT, staff_id TEXT, role TEXT, PRIMARY KEY (reservation_id, staff_id))')
    conn.execute('DELETE FROM reservation_access WHERE reservation_id = ? AND role = ?', (reservation_id, 'server'))
    conn.execute("INSERT OR REPLACE INTO reservation_access (reservation_id, staff_id, role) SELECT ?, staff_id, 'server' FROM table_assignments WHERE table_id = ?", (reservation_id, table_id))

def move_reservation_to_new_table(reservation_id: str, new_table_id: str, new_time: str) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT table_id, reservation_time FROM reservations WHERE id = ?', (reservation_id,)).fetchone()
        if row is None:
            return {'success': False, 'error': 'Reservation not found'}
        conn.execute('UPDATE reservations SET table_id = ?, reservation_time = ? WHERE id = ?', (new_table_id, new_time, reservation_id))
        _grant_table_staff_access(conn, reservation_id, new_table_id)
        conn.commit()
    finally:
        conn.close()
    return {'success': True, 'reservation_id': reservation_id, 'old_table_id': row[0], 'old_time': row[1], 'new_table_id': new_table_id, 'new_time': new_time}
